; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			pop de
			pop hl
			pop bc
			ld b, c
			jr ntc_strcpy_loop

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printtab ntc_data ntc_plat_screen
;kw_printtab, <nvar>  - Tab(n) in Print: spaces up to column n (1 based),
;  a new line first when the cursor is already past it. n off the line: nothing
kw_printtab:
			pop hl
			ld a, (hl)
			dec a
			ld hl, ntc_scols
			cp (hl)
			ret nc
			ld (ntc_tabcol), a
			ld hl, ntc_curx
			cp (hl)
			jr nc, ntc_pt_loop
			ld ix, ntc_pt_loop
			jp ntc_plat_newline
ntc_pt_loop:
			ld a, (ntc_tabcol)
			ld hl, ntc_curx
			cp (hl)
			ret z
			ret c
			ld a, ' '
			ld ix, ntc_pt_loop
			jp ntc_plat_putc
ntc_tabcol:		db 0

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## ntc_paddr
; HL = descriptor, DE = index var: HL = element address, BC = element
; size. jp (ix). Descriptor (12 bytes): base, lower bound 1, lower bound 2,
; count 1, count 2, element size (a 1 dimension array has count 2 = 1)
ntc_paddr:
			ld a, (de)
			ld (ntc_pidx), a
			inc de
			ld a, (de)
			ld (ntc_pidx+1), a
			ld (ntc_pdesc), hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld (ntc_pbase), de
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld hl, (ntc_pidx)
			or a
			sbc hl, de
			ld (ntc_pidx), hl
; (ntc_pidx) = element number, (ntc_pbase) = base, (ntc_pdesc) = descriptor
ntc_pa_tail:
			ld hl, (ntc_pdesc)
			ld bc, 10
			add hl, bc
			ld c, (hl)
			inc hl
			ld b, (hl)
			ld de, (ntc_pidx)
			ld hl, (ntc_pbase)
			ld a, c
ntc_pa_mul:
			add hl, de
			dec a
			jr nz, ntc_pa_mul
			jp (ix)
ntc_pidx:		dw 0
ntc_pbase:		dw 0
ntc_pdesc:		dw 0

;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			pop hl
			pop de
			ld ix, ntc_pg_a
			jp ntc_paddr
ntc_pg_a:
			pop de
			ldir
			ret

;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			pop hl
			pop de
			ld ix, ntc_ps_a
			jp ntc_paddr
ntc_ps_a:
			ex de, hl
			pop hl
			ldir
			ret

;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src, cut at the element
kw_psets:
			pop hl
			pop de
			ld ix, ntc_pss_a
			jp ntc_paddr
ntc_pss_a:
			ex de, hl
			pop hl
			ld a, c
			dec a
			ld b, a
			jp ntc_strcpy_loop

;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			pop hl
			inc hl
			inc hl
			pop de
			ldi
			ldi
			ret

;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			pop hl
			inc hl
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			inc hl
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			dec hl
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; Long (32 bit signed). A Long is 4 bytes, low byte first. Every
; argument is an address (a literal is a dw lo, hi in the data).
; Work space ntc_la / ntc_lb / ntc_lr / ntc_lt.
; ============================================================

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

;## ntc_lcmp ntc_ldata
; DE = a, HL = b: work out a - b. ntc_lsgn = #80 if a < b (signed),
; ntc_lcnt = 0 if a = b. jp (ix) back.
ntc_lcmp:
			ld a, (de)
			sub (hl)
			ld (ntc_lr), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+3), a
			ld b, 0
			jp po, ntc_lcm_nov
			ld b, #80
ntc_lcm_nov:
			xor b
			and #80
			ld (ntc_lsgn), a
			ld hl, ntc_lr
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld (ntc_lcnt), a
			jp (ix)

;## kw_l_cpeq ntc_lcmp
;kw_l_cpeq, <a>, <b>  - Z if a = b
kw_l_cpeq:
			pop de
			pop hl
			ld ix, ntc_lceq
			jp ntc_lcmp
ntc_lceq:
			ld a, (ntc_lcnt)
			or a
			ret

;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

;## kw_l_print ntc_ltoa ntc_printbuf
;kw_l_print, <long>  - print a Long
kw_l_print:
			pop hl
			ld de, ntc_numbuf
			ld ix, ntc_lpr_back
			jp ntc_ltoa
ntc_lpr_back:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; not used (a stream has no rows)
ntc_scols:		db 80			; columns
ntc_bdosa:		db 0			; ntc_bdos: A on return
				ds 256			; the program's real stack
ntc_cpmstack:

;## ntc_plat_bdos ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_bdos - C = BDOS function, DE = argument. A (also in ntc_bdosa)
; and HL come back. IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_bdos:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call 5
			di
			ld sp, (ntc_ip)
			ld (ntc_bdosa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
; ntc_plat_putc - A = character: BDOS 6, count the column
ntc_plat_putc:
			ld e, a
			ld c, 6
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_bdos
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; the terminal wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld e, 13
			ld c, 6
			ld ix, ntc_nl_lf
			jp ntc_bdos
ntc_nl_lf:
			ld e, 10
			ld c, 6
			ld ix, ntc_nl_done
			jp ntc_bdos
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)

; ntc_plat_backspace - BS, space, BS (only on the current line)
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_curx), a
			ld (ntc_pclink), ix
			ld e, 8
			ld c, 6
			ld ix, ntc_bs_sp
			jp ntc_bdos
ntc_bs_sp:
			ld e, ' '
			ld c, 6
			ld ix, ntc_bs_back
			jp ntc_bdos
ntc_bs_back:
			ld e, 8
			ld c, 6
			ld ix, (ntc_pclink)
			jp ntc_bdos
ntc_bs_none:
			jp (ix)

	IF NTC_TERM = 0
; ntc_plat_cls - a stream can't be cleared: a new line (unless at the start)
ntc_plat_cls:
			ld a, (ntc_curx)
			or a
			jr nz, ntc_plat_newline
			jp (ix)

; ntc_plat_locate - nothing on a stream
ntc_plat_locate:
			jp (ix)
	ELSE
; ntc_plat_cls - clear and home with the terminal's codes
ntc_plat_cls:
			xor a
			ld (ntc_curx), a
			ld hl, ntc_term_cls
			jp ntc_cpm_puts

; ntc_plat_locate - H = column, L = row, 1 based (kept on an 80 x 24 screen)
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc a
ntc_lc_x:
			cp 81
			jr c, ntc_lc_xok
			ld a, 80
ntc_lc_xok:
			ld h, a
			dec a
			ld (ntc_curx), a
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc a
ntc_lc_y:
			cp 25
			jr c, ntc_lc_yok
			ld a, 24
ntc_lc_yok:
			ld l, a
			ld de, ntc_term_buf
		IF NTC_TERM = 1
			; VT52: ESC Y row+31 column+31
			ld a, 27
			ld (de), a
			inc de
			ld a, 'Y'
			ld (de), a
			inc de
			ld a, l
			add a, 31
			ld (de), a
			inc de
			ld a, h
			add a, 31
			ld (de), a
			inc de
		ELSE
			; ANSI: ESC [ row ; column H
			ld a, 27
			ld (de), a
			inc de
			ld a, '['
			ld (de), a
			inc de
			ld a, l
			ld b, '0' - 1
ntc_lc_r10:
			inc b
			sub 10
			jr nc, ntc_lc_r10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_r1
			ld (de), a
			inc de
ntc_lc_r1:
			ld a, c
			ld (de), a
			inc de
			ld a, ';'
			ld (de), a
			inc de
			ld a, h
			ld b, '0' - 1
ntc_lc_c10:
			inc b
			sub 10
			jr nc, ntc_lc_c10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_c1
			ld (de), a
			inc de
ntc_lc_c1:
			ld a, c
			ld (de), a
			inc de
			ld a, 'H'
			ld (de), a
			inc de
		ENDIF
			xor a
			ld (de), a
			ld hl, ntc_term_buf
			jp ntc_cpm_puts

; ntc_cpm_puts - HL = 0 terminated codes, each through BDOS 6
ntc_cpm_puts:
			ld (ntc_cplink), ix
ntc_cps_loop:
			ld a, (hl)
			or a
			jr z, ntc_cps_done
			inc hl
			ld (ntc_cpsp), hl
			ld e, a
			ld c, 6
			ld ix, ntc_cps_next
			jp ntc_bdos
ntc_cps_next:
			ld hl, (ntc_cpsp)
			jr ntc_cps_loop
ntc_cps_done:
			ld ix, (ntc_cplink)
			jp (ix)
ntc_cplink:		dw 0
ntc_cpsp:		dw 0
ntc_term_buf:	ds 10
		IF NTC_TERM = 1
ntc_term_cls:	db 27, "E", 27, "H", 0		; VT52: clear, home
		ELSE
ntc_term_cls:	db 27, "[2J", 27, "[H", 0	; ANSI: clear, home
		ENDIF
	ENDIF

; ntc_plat_mode - nothing on a terminal
ntc_plat_mode:
			jp (ix)
ntc_pclink:		dw 0

;## ntc_plat_key ntc_plat_bdos ntc_data
; ntc_plat_scankey - A = key or 0 (BDOS 6, E = #FF)
ntc_plat_scankey:
			ld e, #FF
			ld c, 6
			jp ntc_bdos

; ntc_plat_getkey - wait for a key (BDOS 6 until there is one)
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld e, #FF
			ld c, 6
			ld ix, ntc_gk_back
			jp ntc_bdos
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_frame
ntc_plat_frame:
			jp (ix)

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - warm boot back to CP/M
ntc_plat_exit:
			jp 0

; ============================================================
; File system (FileSystem class) - BDOS files, FCBs, 128 byte records
; ============================================================
; The class's methods are keywords: they take their arguments
; into fs_a1 .. fs_a3, the result's address into fs_res, and
; jump to fs_go with HL = the routine. fs_go runs the routine on
; the real stack (call / push are fine there, as for BDOS), with
; interrupts on, and stores its HL result at fs_res (fs_go4: a
; Long, high word in fs_hi; fs_go0: no store - the routine writes
; the result itself). A routine that fails jumps to fs_err with
; HL = the status (negative); fs_err unwinds to fs_go.
;
; Slots: 0 is for Load / Save / Delete / Exists / Rename / Size,
; 1 and 2 are the handles Open gives. A slot is FS_SLOT bytes:
;   +0  FCB (36)    +36 mode (0 free, 1 read, 2 write, 3 update)
;   +37 position in the buffer (0-128)
;   +38 buffer state (0 not loaded, 1 loaded, 2 changed)
;   +39 record number in the buffer (2)   +42 buffer (128)
; Every record goes through random read / write (BDOS 33 / 34),
; so reading, writing and Seek all work the same way.

FS_SLOT		equ 170
FS_MODE		equ 36
FS_BPOS		equ 37
FS_BST		equ 38
FS_RECL		equ 39
FS_RECH		equ 40
FS_BUF		equ 42
FS_MAXH		equ 2

FS_NOTFOUND	equ -2
FS_FULL		equ -3
FS_BADNAME	equ -4
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOF		equ -7
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_EXISTS	equ -10
FS_BADMODE	equ -11

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: the BDOS (its address is at 6; the CCP below it is free, the program
; ends with a warm boot). Called on the real stack (call / ret), only by the
; Memory class.
ntc_plat_memtop:
			ld hl, (6)
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_nums		equ ntc_bss + 0		; 12 bytes
arr_odd		equ ntc_bss + 12		; 8 bytes
arr_words		equ ntc_bss + 20		; 123 bytes
arr_big		equ ntc_bss + 143		; 16 bytes
arr_grid		equ ntc_bss + 159		; 24 bytes
pa_total_a		equ ntc_bss + 183		; 12 bytes
pa_sortup_a		equ ntc_bss + 195		; 12 bytes
pa_lo_a		equ ntc_bss + 207		; 12 bytes
pa_hi_a		equ ntc_bss + 219		; 12 bytes
pa_count_a		equ ntc_bss + 231		; 12 bytes
pa_longest_s		equ ntc_bss + 243		; 12 bytes
pa_shout_s		equ ntc_bss + 255		; 12 bytes
pa_bigsum_v		equ ntc_bss + 267		; 12 bytes
ntc_bss_size	equ 279
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
